fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        // If input is empty, return empty vector.
        return Vec::new();
    }

    // Result vector will contain 2n - 1 elements.
    let mut res = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            // Insert delimiter before the current element except for the first.
            res.push(delim);
        }
        res.push(num);
    }

    res
}